package com.crms.entity;import jakarta.persistence.*;@Entity public class Company{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@OneToOne(optional=false)private User owner;private String name,description,website,industry;public Long getId(){return id;}public User getOwner(){return owner;}public void setOwner(User v){owner=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getWebsite(){return website;}public void setWebsite(String v){website=v;}public String getIndustry(){return industry;}public void setIndustry(String v){industry=v;}}
